<template><section class="page-reg"><header><h1>Реестр расходов ЦФО · {{ cardId }}</h1><select v-model="sheetName" @change="load"><option v-for="s in registry?.sheets||[]" :key="s.name" :value="s.name">{{ s.label }}</option></select><button :disabled="busy||registry?.read_only" @click="add">Добавить строку</button></header><p v-if="registry?.configuration_pending" class="banner banner-info">Схема листа ожидает подтверждения конфигурации; строки можно редактировать вручную.</p><p v-if="api.error.value" class="banner banner-neg">{{ api.error.value }}</p><table v-if="registry"><thead><tr><th v-for="f in fields" :key="f.key">{{ f.label }}</th><th v-for="m in 12" :key="m">{{ m }}</th><th>Итого</th><th></th></tr></thead><tbody><tr v-for="row in registry.rows" :key="row.id"><td v-for="f in fields" :key="f.key"><input :value="String(row.attrs[f.key]??'')" :disabled="registry.read_only" @change="setAttr(row,f.key,($event.target as HTMLInputElement).value,f.type)" /></td><td v-for="m in 12" :key="m"><input inputmode="decimal" :value="row.months[String(m)]===null||row.months[String(m)]===undefined?'':String(row.months[String(m)])" :disabled="registry.read_only" @change="setMonth(row,m,($event.target as HTMLInputElement).value)" /></td><td>{{ row.total??0 }}</td><td><button @click="copy(row)">копия</button><button @click="remove(row)" :disabled="registry.read_only">удалить</button></td></tr></tbody><tfoot><tr><td :colspan="fields.length+12">Итого</td><td>{{ registry.total }}</td></tr></tfoot></table></section></template>
<script setup lang="ts">
import { useCfoExpenseRegistry,type CfoRegistry,type CfoRegistryRow } from "~/composables/useCfoExpenseRegistry";
const route=useRoute();const cardId=Number(route.params.cardId);const api=useCfoExpenseRegistry();const registry=ref<CfoRegistry|null>(null);const sheetName=ref("");const busy=ref(false);const fields=computed(()=>registry.value?.sheets.find(s=>s.name===sheetName.value)?.fields||[]);
async function load(){if(!sheetName.value){registry.value=await api.get(cardId,"catalog");sheetName.value=registry.value.sheets[0]?.name||""}if(sheetName.value)registry.value=await api.get(cardId,sheetName.value)}
async function add(){busy.value=true;try{await api.save(cardId,sheetName.value,{sheet:sheetName.value,attrs:{},months:{}});await load()}finally{busy.value=false}}
async function setAttr(row:CfoRegistryRow,key:string,value:string,type:string){const n=Number(value); row.attrs[key]=type==="number"?(Number.isFinite(n)?n:0):value;await api.save(cardId,sheetName.value,row);await load()}
async function setMonth(row:CfoRegistryRow,month:number,value:string){const n=Number(value); row.months[String(month)]=value.trim()===""?null:(Number.isFinite(n)?n:null);await api.save(cardId,sheetName.value,row);await load()}
async function copy(row:CfoRegistryRow){await api.copy(cardId,sheetName.value,row.id);await load()}
async function remove(row:CfoRegistryRow){await api.remove(cardId,sheetName.value,row.id);await load()}
onMounted(load)
</script>
